using System.Drawing.Design;
using System.Windows.Forms;
using System.Windows.Forms.Design;

static class Program
{
    [STAThread]
    static void Main()
    {
        ApplicationConfiguration.Initialize();
        Application.Run(new MainForm());
    }
}

class MainForm : Form
{
    private readonly StatusStrip _statusStrip;

    public MainForm()
    {
        _statusStrip = new StatusStrip();
        // .NET 9 behavioral change: StatusStrip default renderer changed.
        // Explicitly set RenderMode to preserve .NET 8 appearance.
        _statusStrip.RenderMode = ToolStripRenderMode.System;
        Controls.Add(_statusStrip);
    }
}

// .NET 9 nullability change: IWindowsFormsEditorService.DropDownControl
// parameter is now non-nullable. Guard against null before calling.
class MyEditor : UITypeEditor
{
    public override object? EditValue(
        System.ComponentModel.ITypeDescriptorContext? context,
        IServiceProvider provider,
        object? value)
    {
        var editorService = provider.GetService(typeof(IWindowsFormsEditorService))
            as IWindowsFormsEditorService;

        if (editorService is null)
            return value;

        var control = CreateDropDownControl(value);
        if (control is not null)
        {
            editorService.DropDownControl(control);
            value = GetValueFromControl(control);
        }

        return value;
    }

    private Control? CreateDropDownControl(object? value)
    {
        // Return null when no suitable editor control can be created;
        // caller now guards against passing null to DropDownControl.
        if (value is null)
            return null;
        return new ListBox();
    }

    private object? GetValueFromControl(Control control) => (control as ListBox)?.SelectedItem;
}

